CREATE OR REPLACE FUNCTION public.combat_hit_core(p_cp integer, p_wmult numeric, p_buff numeric, p_debuff numeric, p_synmult numeric, p_critchance numeric, p_miss numeric, p_armored_melee boolean, p_expose numeric, p_mods jsonb, p_elem jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
