      v_double := true;
    end if;
  end if;
  v_hit := jsonb_build_object('dmg', v_dmg, 'outcome', v_outcome, 'miss', v_miss, 'crit', v_crit, 'block', v_block, 'double', v_double);
  if p_elem is not null and v_m <> 1 and not v_miss then
